//! The name-map test of RF-14. `conformance/api/voice-params.json` is generated by
//! `bun run voice-params:record` from the `VoiceParams` interface of `src/types.ts`; the serde names of
//! the Rust struct must equal it exactly, so saved settings keep working.

use std::collections::BTreeSet;

use serde_json::{Value, json};
use undertone_engine::params::{
	AutopanShape, FmEnvCurve, FmWave, PanPoint, Pitch, SoundType, VoiceParams,
};

/// Required in the TypeScript type, but `.s(name)` sets it to `undefined`, so a sample voice has no key.
const REQUIRED_BUT_ABSENT_FOR_SAMPLES: &str = "soundType";

const SNAPSHOT: &str = include_str!("../../../conformance/api/voice-params.json");

struct Field {
	name: String,
	optional: bool,
	type_text: String,
}

fn snapshot_fields() -> Vec<Field> {
	let snapshot: Value = serde_json::from_str(SNAPSHOT).expect("the snapshot is JSON");
	snapshot["fields"]
		.as_array()
		.expect("the snapshot has a field list")
		.iter()
		.map(|f| Field {
			name: f["name"].as_str().expect("name").to_owned(),
			optional: f["optional"].as_bool().expect("optional"),
			type_text: f["type"].as_str().expect("type").to_owned(),
		})
		.collect()
}

/// A valid JSON value for a TypeScript type text. A new type text must be added here on purpose.
fn sample_value(type_text: &str) -> Value {
	match type_text {
		"SoundType" | "OscType | ShapedWaveType" | "'sine' | 'triangle' | 'square'" => {
			json!("sine")
		}
		"string | number" => json!("c3"),
		"string" => json!("kick"),
		"number" => json!(0.5),
		"number[]" => json!([0.25, 0.5]),
		"PanPoint[]" => json!([{ "time": 0.0, "pan": -1.0 }, { "time": 0.5, "pan": 1.0 }]),
		"'lin' | 'exp'" => json!("lin"),
		other => {
			panic!("a VoiceParams field has the new type `{other}`: teach this test its JSON form")
		}
	}
}

fn keys(value: &Value) -> BTreeSet<String> {
	value
		.as_object()
		.expect("an object")
		.keys()
		.cloned()
		.collect()
}

#[test]
fn a_fully_set_voice_serialises_exactly_the_snapshot_names() {
	let full = VoiceParams {
		sound_type: Some(SoundType::Square),
		pitch: Some(Pitch::Hz(440.0)),
		sample_name: Some("kick".into()),
		sample_bank: Some("tr808".into()),
		filter_cutoff: Some(800.0),
		hpf_cutoff: Some(100.0),
		phaser_rate: Some(0.5),
		room_level: Some(0.2),
		delay_level: Some(0.3),
		orbit: Some(1.0),
		pitch_env_amount: Some(12.0),
		pitch_attack: Some(0.0),
		pitch_decay: Some(0.1),
		pitch_steps: Some(vec![0.0, 3.0]),
		pitch_step_rate: Some(140.0),
		fm_index: Some(2.0),
		fm_harmonicity: Some(1.5),
		fm_attack: Some(0.0),
		fm_decay: Some(0.1),
		fm_sustain: Some(0.5),
		fm_release: Some(0.2),
		fm_env_curve: Some(FmEnvCurve::Lin),
		fm_wave: Some(FmWave::Halfsine),
		pan: Some(-0.5),
		pan_path: Some(vec![
			PanPoint {
				time: 0.0,
				pan: -1.0,
			},
			PanPoint {
				time: 0.5,
				pan: 1.0,
			},
		]),
		autopan: Some(2.0),
		autopan_depth: Some(0.5),
		autopan_shape: Some(AutopanShape::Triangle),
		autopan_phase: Some(0.25),
		pan_slide_from: Some(-1.0),
		pan_slide_time: Some(0.2),
		pan_law: Some(-4.5),
		channel_gains: Some(vec![1.0, 0.0]),
		duration: Some(0.5),
		legato: Some(0.9),
		velocity: Some(0.7),
		cut_group: Some(1.0),
		..VoiceParams::empty()
	};
	let json = serde_json::to_value(&full).expect("serialises");
	let expected: BTreeSet<String> = snapshot_fields().into_iter().map(|f| f.name).collect();
	assert_eq!(expected.len(), 52);
	assert_eq!(
		keys(&json),
		expected,
		"the serde names differ from conformance/api/voice-params.json"
	);
}

#[test]
fn an_empty_voice_serialises_exactly_the_required_names() {
	let json = serde_json::to_value(VoiceParams::empty()).expect("serialises");
	let required: BTreeSet<String> = snapshot_fields()
		.into_iter()
		.filter(|f| !f.optional)
		.map(|f| f.name)
		.collect();
	assert_eq!(keys(&json), required);
}

#[test]
fn an_object_built_from_the_snapshot_names_deserialises_and_serialises_back() {
	let object: serde_json::Map<String, Value> = snapshot_fields()
		.into_iter()
		.map(|f| (f.name, sample_value(&f.type_text)))
		.collect();
	let input = Value::Object(object);
	let params: VoiceParams =
		serde_json::from_value(input.clone()).expect("every name is accepted");
	assert_eq!(serde_json::to_value(&params).expect("serialises"), input);
}

#[test]
fn a_required_field_is_required_and_an_optional_one_may_be_missing() {
	for field in snapshot_fields() {
		let mut object: serde_json::Map<String, Value> = snapshot_fields()
			.into_iter()
			.map(|f| (f.name, sample_value(&f.type_text)))
			.collect();
		object.remove(&field.name);
		let parsed = serde_json::from_value::<VoiceParams>(Value::Object(object));
		let may_be_missing = field.optional || field.name == REQUIRED_BUT_ABSENT_FOR_SAMPLES;
		assert_eq!(parsed.is_ok(), may_be_missing, "field {}", field.name);
	}
}
